function renderJournal(){$('#journal').replaceChildren();pet.journal.slice(0,6).forEach(m=>{const a=document.createElement('article');a.className='moment';const i=document.createElement('span');i.className='moment-icon';i.textContent=m.icon||'♡';const d=document.createElement('div'),b=document.createElement('strong'),s=document.createElement('small');b.textContent=m.text;s.textContent=new Date(m.time).toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · '+new Date(m.time).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});d.append(b,s);a.append(i,d);$('#journal').append(a)});$('#journal-count').textContent=pet.journal.length}
const statInfo=[['food','Full tummy','#c9946b'],['happiness','Happiness','#9dac81'],['energy','Energy','#d0b15c'],['cleanliness','Fresh & fluffy','#91aca0']];
statInfo.forEach(([key,label,color])=>{const a=document.createElement('div');a.innerHTML=`<div class="stat-line"><b>${label}</b><span id="${key}-value"></span></div><div class="track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" id="${key}-bar"><div class="fill" style="background:${color}" id="${key}-fill"></div></div>`;$('#stats').append(a)});
function refresh(){$('#pet-name').textContent=pet.name;$('#mood').textContent=mood(pet);$('#age').textContent='DAY '+String(Math.max(1,Math.floor((Date.now()-pet.born)/86400000)+1)).padStart(2,'0');for(const [key] of statInfo){const v=Math.round(pet[key]);$('#'+key+'-value').textContent=v+'%';$('#'+key+'-fill').style.width=v+'%';$('#'+key+'-bar').setAttribute('aria-valuenow',v)}$('#bond-count').textContent=pet.cuddles+' cuddle'+(pet.cuddles===1?'':'s');$('#bond-label').textContent=pet.bond>=100?'Best little friends':pet.bond>=40?'Growing closer':pet.bond>=15?'A familiar face':'Getting to know you';$('#sleep-label').textContent=pet.sleeping?'Wake up':'Rest';$('#sleep-detail').textContent=pet.sleeping?'Hello, sleepyhead':'Dream of little things';document.body.classList.toggle('night',pet.sleeping);$('#room-label').textContent=pet.sleeping?'A quiet, moonlit corner':'A sunny little corner';$('#care-tip').textContent=pet.sleeping?'Resting restores energy, even while you’re away.':pet.food<25?'A tasty snack would be lovely right now.':pet.energy<25?'A little nap will put the bounce back.':'A snack, a game, or simply being here.';$('#sound span').textContent=pet.sound?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',String(pet.sound));$('#sound').setAttribute('aria-label',pet.sound?'Disable sound':'Enable sound')}
function sound(kind='meow'){if(!pet.sound)return;try{soundContext??=new (window.AudioContext||window.webkitAudioContext)();soundContext.resume();const t=soundContext.currentTime,o=soundContext.createOscillator(),g=soundContext.createGain();o.type=kind==='purr'?'sine':'triangle';o.frequency.setValueAtTime(kind==='purr'?110:620,t);o.frequency.exponentialRampToValueAtTime(kind==='purr'?90:920,t+.14);o.frequency.exponentialRampToValueAtTime(kind==='purr'?80:430,t+.42);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.04);g.gain.exponentialRampToValueAtTime(.001,t+.5);o.connect(g);g.connect(soundContext.destination);o.start(t);o.stop(t+.55)}catch{}}
function floats(symbol='♡'){for(let k=0;k<4;k++){setTimeout(()=>{const s=document.createElement('span');s.className='floating';s.textContent=symbol;s.style.left=(40+Math.random()*25)+'%';s.style.top=(35+Math.random()*20)+'%';s.style.setProperty('--drift',(Math.random()*70-35)+'px');$('#float-layer').append(s);setTimeout(()=>s.remove(),1800)},k*150)}}
function act(a,snack){advance(pet);if(!ready&&a!=='sleep'){toast('Your kitten is still settling in. One moment.');return}if(action==='play'&&a!=='sleep'){toast('Playtime is in progress. Move the toy around!');return}const r=care(pet,a,snack);if(!r.ok){toast(r.message);return}action=a;actionStart=performance.now();if(a==='feed'){const name={kibble:'crunchy kibble',salmon:'salmon bites',chicken:'chicken morsels'}[snack];say('Mmm. '+name+'? You know the way to my heart.');moment('A happy tummy, thanks to '+name+'.','◡');floats('✦');sound();}else if(a==='brush'){say('Oh, that’s the spot. Fluffy again!');moment('Freshly brushed & feeling fabulous.','≋');floats('✧');sound('purr')}else if(a==='play'){playEnd=performance.now()+15000;say('Catch me if you can! Move the toy around.');$('#scene-hint').textContent='Move your finger or pointer to guide the toy · 15 seconds';moment('A little mischief. A lot of fun.','✺');sound()}else if(a==='sleep'){playEnd=0;action=pet.sleeping?'sleep':'idle';say(pet.sleeping?'Zzz… dreaming of tiny adventures.':'Good morning, my favorite human.');moment(pet.sleeping?'Tucked in for sweet little dreams.':'Hello again, sleepyhead.','☾');$('#scene-hint').textContent='Tap your kitten for a little love · drag to look around';}else if(a==='pet'){say(['I like it here. Especially with you.','More of that, please.','You have excellent petting skills.'][Math.floor(Math.random()*3)]);floats();sound('purr');if(pet.cuddles%5===0)moment('Five more cuddles. One very happy cat.')}refresh();save()}
$('.actions').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='feed'){if(pet.sleeping){toast('Wake your kitten before snack time.');return}$('#feed-dialog').showModal()}else act(b.dataset.action)});
$('.snacks').addEventListener('click',e=>{const b=e.target.closest('[data-snack]');if(b){$('#feed-dialog').close();act('feed',b.dataset.snack)}});
$('#rename').onclick=()=>{$('#name-input').value=pet.name;$('#name-dialog').showModal();$('#name-input').focus()};$('#close-name').onclick=()=>$('#name-dialog').close();$('#name-form').onsubmit=e=>{e.preventDefault();const name=$('#name-input').value.trim();if(!name)return;pet.name=name.slice(0,24);moment('A name to love: '+pet.name+'.');refresh();$('#name-dialog').close();toast('Hello, '+pet.name+' ♡')};$('#sound').onclick=()=>{pet.sound=!pet.sound;refresh();save();if(pet.sound)sound()};$('#view').onclick=()=>{desiredAngle+=Math.PI/4};
$('.tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;$('.tabs').querySelectorAll('button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});$('#journal').hidden=b.dataset.tab!=='journal';$('#guide').hidden=b.dataset.tab!=='guide'};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
refresh();renderJournal();setInterval(()=>{advance(pet);refresh();save()},15000);document.addEventListener('visibilitychange',()=>{advance(pet);refresh();save()});window.addEventListener('pagehide',save);
