let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;host.prepend(renderer.domElement)}catch(e){$('#loading strong').textContent='Your browser couldn’t open the 3D room.';$('#load-progress').textContent='Try a browser with WebGL enabled.';console.error(e)}
const ambient=new THREE.HemisphereLight(0xfff6de,0x8c9980,2.5);scene.add(ambient);const sun=new THREE.DirectionalLight(0xffedce,3.7);sun.position.set(-3,6,4);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-5;sun.shadow.camera.right=5;sun.shadow.camera.top=5;sun.shadow.camera.bottom=-5;sun.shadow.bias=-.0005;scene.add(sun);const fill=new THREE.DirectionalLight(0xf4fbef,1.4);fill.position.set(4,2,-2);scene.add(fill);
