const rug=mesh(new THREE.CylinderGeometry(1.95,1.95,.035,96),mat('#aab794'));rug.scale.z=.79;rug.position.set(0,-.005,.02);const rugRim=mesh(new THREE.TorusGeometry(1.86,.008,6,96),mat('#cbd2b9'));rugRim.rotation.x=-Math.PI/2;rugRim.scale.y=.79;rugRim.position.y=.015;
const wall=mesh(new THREE.PlaneGeometry(40,12),mat('#eeeadc'));wall.position.set(0,5,-3.5);wall.receiveShadow=true;const skirting=mesh(new THREE.BoxGeometry(40,.16,.08),mat('#d7d5c3'));skirting.position.set(0,.06,-3.44);
// A small window and its soft light patch.
const windowFrame=new THREE.Group();windowFrame.position.set(-2.55,2.1,-3.43);scene.add(windowFrame);const glass=mesh(new THREE.PlaneGeometry(1.8,2.2),new THREE.MeshBasicMaterial({color:0xdde6d1}),windowFrame);for(const x of [-.97,0,.97]){const bar=mesh(new THREE.BoxGeometry(.075,2.4,.08),mat('#faf7e9'),windowFrame);bar.position.set(x,0,.03)}for(const y of [-1.16,0,1.16]){const bar=mesh(new THREE.BoxGeometry(2,.075,.08),mat('#faf7e9'),windowFrame);bar.position.set(0,y,.03)}
const patch=mesh(new THREE.PlaneGeometry(1.9,2.5),new THREE.MeshBasicMaterial({color:0xfff4cc,transparent:true,opacity:.28,depthWrite:false}));patch.rotation.set(-Math.PI/2,0,-.2);patch.position.set(-1.6,.005,-.9);patch.receiveShadow=false;patch.castShadow=false;
const bowl=new THREE.Group();bowl.position.set(1.6,.12,.9);scene.add(bowl);mesh(new THREE.CylinderGeometry(.31,.25,.17,48,1,true),new THREE.MeshStandardMaterial({color:0xc79c78,side:THREE.DoubleSide,roughness:.55}),bowl);const rim=mesh(new THREE.TorusGeometry(.305,.035,10,48),mat('#dfbc95'),bowl);rim.rotation.x=Math.PI/2;rim.position.y=.075;const food=mesh(new THREE.CylinderGeometry(.25,.22,.035,32),mat('#937454'),bowl);food.position.y=-.02;for(let i=0;i<16;i++){const k=mesh(new THREE.SphereGeometry(.026,6,4),mat(i%2?'#8b6a43':'#ae8857'),bowl);const a=i*2.4,r=.2*Math.sqrt((i+1)/16);k.position.set(Math.cos(a)*r,.015,Math.sin(a)*r)}
const cushion=mesh(new THREE.CylinderGeometry(.8,.78,.19,48),mat('#c2b09a'));cushion.scale.z=.63;cushion.position.set(1.35,.075,-1.6);
const bag=new THREE.Group();bag.position.set(-1.6,.02,-1.3);bag.rotation.y=.2;scene.add(bag);const paper=mat('#bc9266');const bottom=mesh(new THREE.BoxGeometry(.75,.035,.55),paper,bag);for(const x of [-.375,.375]){const s=mesh(new THREE.BoxGeometry(.02,.86,.55),paper,bag);s.position.set(x,.43,0)}for(const z of [-.275,.275]){const s=mesh(new THREE.BoxGeometry(.75,.86,.02),paper,bag);s.position.set(0,.43,z)}for(const x of [-.2,.2]){const h=mesh(new THREE.TorusGeometry(.13,.015,6,24,Math.PI),mat('#92734f'),bag);h.position.set(x,.86,0)}
const toy=mesh(new THREE.SphereGeometry(.12,24,16),mat('#cf8058'));toy.position.set(-.9,.13,1.15);const stripe=mesh(new THREE.TorusGeometry(.121,.007,6,32),mat('#efd0a1'),toy);stripe.rotation.x=.6;
const moon=new THREE.DirectionalLight(0xafc8fa,0);moon.position.set(-3,4,4);scene.add(moon);const catPivot=new THREE.Group();scene.add(catPivot);let baseY=0,baseScale=1;
new GLTFLoader().load('./assets/kitten.glb',g=>{model=g.scene;model.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(model),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());baseScale=1.75/size.y;model.scale.setScalar(baseScale);model.position.set(-center.x*baseScale,-bounds.min.y*baseScale,-center.z*baseScale);baseY=model.position.y;catPivot.add(model);model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;if(o.material){o.material.metalness=0;o.material.roughness=.86}}if(o.isBone){bones[o.name]={node:o,base:o.quaternion.clone()}}});ready=true;$('#loading').hidden=true;say(pet.sleeping?'Zzz… dreaming of tiny adventures.':'Hello, human. Got a little time for me?')},p=>{if(p.total)$('#load-progress').textContent=Math.round(p.loaded/p.total*100)+'% · bringing your kitten home'},e=>{$('#loading strong').textContent='Your kitten couldn’t load.';$('#load-progress').textContent='Please reload to try again.';console.error(e)});
const pointer=new THREE.Vector2(),ray=new THREE.Raycaster(),ground=new THREE.Plane(new THREE.Vector3(0,1,0),-.14),toyTarget=toy.position.clone();function updatePointer(e){const r=host.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);if(action==='play'){const hit=new THREE.Vector3();if(ray.ray.intersectPlane(ground,hit)){toyTarget.set(Math.max(-1.7,Math.min(1.7,hit.x)),.14,Math.max(-1.2,Math.min(1.4,hit.z)))}}}
host.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,angle:desiredAngle,moved:false};host.setPointerCapture(e.pointerId);updatePointer(e)});host.addEventListener('pointermove',e=>{updatePointer(e);if(drag&&action!=='play'){const dx=e.clientX-drag.x;if(Math.abs(dx)+Math.abs(e.clientY-drag.y)>8)drag.moved=true;desiredAngle=drag.angle+dx*.008}});host.addEventListener('pointerup',e=>{if(drag&&!drag.moved&&action!=='play'&&!pet.sleeping&&model&&performance.now()-petCooldown>900){updatePointer(e);if(ray.intersectObject(model,true).length){petCooldown=performance.now();act('pet')}}drag=null});host.addEventListener('pointercancel',()=>drag=null);
