function resize(){const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.position.set(w/h<1?2.9:3.1,w/h<1?2.8:2.5,w/h<1?6.9:5.4);camera.lookAt(0,.8,0);camera.updateProjectionMatrix();renderer?.setSize(w,h)}new ResizeObserver(resize).observe(host);resize();
let last=performance.now();function animate(now){requestAnimationFrame(animate);if(!renderer||document.hidden)return;const dt=Math.min(.05,(now-last)/1000);last=now;const t=now/1000,elapsed=(now-actionStart)/1000;sun.intensity=THREE.MathUtils.damp(sun.intensity,pet.sleeping?.14:3.7,3,dt);ambient.intensity=THREE.MathUtils.damp(ambient.intensity,pet.sleeping?.7:2.5,3,dt);moon.intensity=THREE.MathUtils.damp(moon.intensity,pet.sleeping?1.8:0,3,dt);glass.material.color.lerp(new THREE.Color(pet.sleeping?'#6d8395':'#dde6d1'),dt*3);patch.visible=!pet.sleeping;
if(model){for(const b of Object.values(bones))b.node.quaternion.copy(b.base);viewAngle=THREE.MathUtils.damp(viewAngle,desiredAngle,5,dt);catPivot.rotation.y=viewAngle;const breath=reduceMotion?0:Math.sin(t*2.2)*.003;model.scale.set(baseScale,baseScale*(1+breath),baseScale);model.position.y=baseY;catPivot.position.x=THREE.MathUtils.damp(catPivot.position.x,0,4,dt);catPivot.position.z=THREE.MathUtils.damp(catPivot.position.z,0,4,dt);if(!reduceMotion){bone('Bone_013',axisZ,Math.sin(t*.8)*.04);if(pet.sleeping){bone('Bone_013',axisX,.13);if(Math.floor(t)%5===0&&Math.random()<.005)floats('z')}else if(action==='feed'&&elapsed<3.2){bone('Bone_013',axisX,.14+Math.sin(t*7)*.04);bowl.scale.setScalar(1+Math.sin(t*6)*.02)}else if(action==='brush'&&elapsed<3){bone('Bone_013',axisZ,Math.sin(elapsed*3)*.07)}else if(action==='pet'&&elapsed<2.3){bone('Bone_013',axisZ,Math.sin(elapsed*4)*.08)}else if(action==='play'&&now<playEnd){toy.position.lerp(toyTarget,.12);toy.rotation.x+=dt*3;toy.rotation.z+=dt*2;const look=THREE.MathUtils.clamp(toy.position.x*.13,-.2,.2);bone('Bone_013',axisZ,look);catPivot.position.x=THREE.MathUtils.damp(catPivot.position.x,toy.position.x*.15,2,dt);bone('Bone_017',axisX,Math.max(0,Math.sin(t*3))*.07);bone('Bone_021',axisX,Math.max(0,Math.sin(t*3+Math.PI))*.07)}}if(action==='play'&&now>=playEnd){action='idle';toy.position.set(-.9,.13,1.15);say('That was fun. Same time tomorrow?');$('#scene-hint').textContent='Tap your kitten for a little love · drag to look around';toast('Playtime complete · happiness +18');floats('✦')}if(['feed','brush','pet'].includes(action)&&elapsed>3.5){action='idle';bowl.scale.setScalar(1)}}renderer.render(scene,camera)}requestAnimationFrame(animate);
